class Solution {
    unordered_map<int,int> height, answer;

    int computeHeight(TreeNode* node) {
        if (!node) return -1;
        int h = 1 + max(computeHeight(node->left), computeHeight(node->right));
        height[node->val] = h;
        return h;
    }

    void dfs(TreeNode* node, int depth, int currentMax) {
        if (!node) return;
        answer[node->val] = currentMax;
        int leftH  = node->left  ? height[node->left->val]  : -1;
        int rightH = node->right ? height[node->right->val] : -1;
        if (node->left)  dfs(node->left,  depth + 1, max(currentMax, depth + 1 + rightH));
        if (node->right) dfs(node->right, depth + 1, max(currentMax, depth + 1 + leftH));
    }

public:
    vector<int> treeQueries(TreeNode* root, vector<int>& queries) {
        height.clear();
        answer.clear();
        computeHeight(root);
        dfs(root, 0, 0);
        vector<int> result;
        result.reserve(queries.size());
        for (int q : queries) result.push_back(answer[q]);
        return result;
    }
};
